input.content:
workspace "Hospital Appointment System" "A minimal C4 model of a hospital appointment system." {

    person {
        patient = person "Patient" "A patient who books and manages hospital appointments."
    }

    softwareSystems {
        appointmentSystem = softwareSystem "Appointment System" "Allows patients to book and manage hospital appointments." {
            bookingWebApp = container "Booking Web App" "A web application that patients use to book and manage appointments." "Web"
            schedulingService = container "Scheduling Service" "Manages appointment scheduling and slot availability." "Service"
        }

        patient -> bookingWebApp "Books and manages appointments" "Browser"
        bookingWebApp -> schedulingService "Reserves appointment slots" "REST/JSON"
    }

    views {
        systemContext appointmentSystem "SystemContext" {
            include *
            autoLayout
        }
    }
}

